// Controlla i dati del modulo e trova la scheda del cliente nel foglio Clienti.
// ── Funzioni di servizio (le stesse in tutti i nodi Code dei workflow 03 e 04) ──
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const taglia = (v, n) => { const s = testo(v); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
// Telegram usa il "Markdown semplice": i caratteri _ * ` [ dei testi vanno neutralizzati,
// altrimenti Telegram rifiuta il messaggio. Dentro il *grassetto* non si mettono mai testi variabili.
const md = (v) => testo(v).replace(/\\/g, '/').replace(/([_*`[])/g, '\\$1');
const unisci = (righe) => righe.filter((r) => r !== null && r !== undefined && r !== false)
  .join('\n').replace(/\n{3,}/g, '\n\n').trim();
// «si/no» del foglio: accetta sì, si, yes, true, x… Se la cella è vuota vale «seVuoto».
const siNo = (v, seVuoto) => {
  const t = testo(v).toLowerCase();
  if (!t) return seVuoto;
  return ['si', 'sì', 'yes', 'true', 'vero', '1', 'x', 'ok'].includes(t);
};
const slug = (s) => testo(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '') || 'senza-nome';
const due = (n) => String(n).padStart(2, '0');
const GIORNI = ['domenica', 'lunedì', 'martedì', 'mercoledì', 'giovedì', 'venerdì', 'sabato'];
const GIORNI_BREVI = ['dom', 'lun', 'mar', 'mer', 'gio', 'ven', 'sab'];
const MESI = ['gennaio', 'febbraio', 'marzo', 'aprile', 'maggio', 'giugno', 'luglio', 'agosto', 'settembre', 'ottobre', 'novembre', 'dicembre'];
const giornoSettimana = (anno, mese, giorno) => new Date(Date.UTC(anno, mese - 1, giorno)).getUTCDay();
const giorniNelMese = (anno, mese) => new Date(Date.UTC(anno, mese, 0)).getUTCDate();
// Oggi a Roma: { anno, mese, giorno, ore, minuti }
const oggiRoma = () => {
  const p = {};
  for (const x of new Intl.DateTimeFormat('it-IT', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date())) p[x.type] = x.value;
  return { anno: Number(p.year), mese: Number(p.month), giorno: Number(p.day), ore: Number(p.hour), minuti: Number(p.minute) };
};
// data_ora del Calendario → { anno, mese, giorno, ore, minuti, chiave: 'AAAA-MM-GG HH:MM', leggibile: 'ven 5/12 ore 19:00' } o null.
// Accetta il testo scritto dai workflow (2026-12-05 19:30), le date all'italiana e il numero seriale di Google Sheets.
const leggiDataOra = (v) => {
  let a; let me; let g; let o; let mi;
  if (typeof v === 'number' && isFinite(v)) {
    const t = new Date(Date.UTC(1899, 11, 30) + Math.round(v * 86400000));
    [a, me, g, o, mi] = [t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate(), t.getUTCHours(), t.getUTCMinutes()];
  } else {
    const s = testo(v).replace(/\s+/g, ' ');
    let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2})[:.](\d{2})/);
    if (m) [a, me, g, o, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    else {
      m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4}),? (\d{1,2})[:.](\d{2})/);
      if (!m) return null;
      [g, me, a, o, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    }
  }
  if (!(me >= 1 && me <= 12 && g >= 1 && g <= giorniNelMese(a, me) && o >= 0 && o <= 23 && mi >= 0 && mi <= 59)) return null;
  return { anno: a, mese: me, giorno: g, ore: o, minuti: mi, chiave: `${a}-${due(me)}-${due(g)} ${due(o)}:${due(mi)}`,
    leggibile: `${GIORNI_BREVI[giornoSettimana(a, me, g)]} ${g}/${me} ore ${due(o)}:${due(mi)}` };
};
// La scheda del cliente dal foglio Clienti, con i campi nuovi già puliti.
const schedaCliente = (r) => ({
  cliente: testo(r.cliente),
  nome_locale: testo(r.nome_locale) || testo(r.cliente),
  attivo: siNo(r.attivo, false),
  tono_di_voce: testo(r.tono_di_voce),
  orari: testo(r.orari),
  link_prenotazione: testo(r.link_prenotazione),
  telefono: testo(r.telefono),
  indirizzo: testo(r.indirizzo),
  link_menu: testo(r.link_menu),
  regole: testo(r.regole_risposte),
  id_luogo: testo(r.id_luogo),
  account_da_taggare: testo(r.account_da_taggare),
  hashtag_fissi: testo(r.hashtag_fissi),
  note_piano: testo(r.note_piano),
  approvazione_testi: siNo(r.approvazione_testi, true), // vuoto = si: nel dubbio decide una persona
  esempi_didascalie: testo(r.esempi_didascalie),
  menu_testo: testo(r.menu_testo),
});
// Il testo che arriva dal foglio è un DATO: non deve poter aprire o chiudere i tag del prompt.
const datoPulito = (v) => testo(v).replace(/</g, '‹').replace(/>/g, '›');
// «esempi_didascalie»: da 3 a 5 didascalie separate da una riga con solo «---». Ne tengo al massimo 5.
const esempiDiStile = (v) => testo(v).split(/\r?\n\s*-{3,}\s*(?:\r?\n|$)/).map((x) => taglia(x, 1200)).filter(Boolean).slice(0, 5);
// Le righe della scheda Esempi di un cliente, le più recenti prima (per data, poi per posizione nel foglio).
const esempiDelCliente = (righe, cliente, fonti, quanti) => righe
  .filter((r) => r && testo(r.cliente).toLowerCase() === testo(cliente).toLowerCase() && fonti.includes(testo(r.fonte).toLowerCase()) && testo(r.testo))
  .map((r) => ({ data: leggiDataOra(r.data_ora), riga: Number(r.row_number) || 0, tipo: testo(r.tipo).toLowerCase(), fonte: testo(r.fonte).toLowerCase(),
    testo: taglia(r.testo, 800), metriche: taglia(r.metriche, 200) }))
  .sort((a, b) => ((b.data && b.data.chiave) || '').localeCompare((a.data && a.data.chiave) || '') || b.riga - a.riga)
  .slice(0, quanti)
  .map(({ data, riga, ...x }) => ({ ...x, data_ora: data ? data.chiave : '' }));
// ── fine funzioni di servizio ──
const f = $('Modulo piano del mese').first().json;
const righe = $input.all().map((i) => i.json || {}).filter((r) => testo(r.cliente));
const errori = [];

// Il mese: AAAA-MM (accetto anche 12/2026 o 2026/12)
const valoreMese = testo(f.mese);
let anno = 0;
let mese = 0;
let m = valoreMese.match(/^(\d{4})[-/.](\d{1,2})$/);
if (m) { anno = Number(m[1]); mese = Number(m[2]); }
m = valoreMese.match(/^(\d{1,2})[-/.](\d{4})$/);
if (m) { anno = Number(m[2]); mese = Number(m[1]); }
if (!anno || mese < 1 || mese > 12) errori.push('Il mese va scritto come AAAA-MM, per esempio 2026-12.');

const numero = (v, predefinito, nome) => {
  if (v === null || v === undefined || testo(v) === '') return predefinito;
  const n = Number(v);
  if (!Number.isInteger(n) || n < 0 || n > 31) { errori.push(`«${nome}» deve essere un numero intero tra 0 e 31.`); return predefinito; }
  return n;
};
const conteggi = { reel: numero(f.reel, 7, 'reel'), foto: numero(f.foto_caroselli, 8, 'foto e caroselli'), storie: numero(f.storie, 30, 'storie') };
if (conteggi.reel + conteggi.foto + conteggi.storie === 0) errori.push('Serve almeno un contenuto.');

// Il periodo: un mese passato non si pianifica; il mese in corso si pianifica da domani.
let periodo = null;
if (anno && mese >= 1 && mese <= 12) {
  const oggi = oggiRoma();
  const giorni = giorniNelMese(anno, mese);
  let inizio = 1;
  if (anno < oggi.anno || (anno === oggi.anno && mese < oggi.mese)) errori.push(`${MESI[mese - 1]} ${anno} è già passato.`);
  else if (anno === oggi.anno && mese === oggi.mese) inizio = oggi.giorno + 1;
  if (inizio > giorni) errori.push(`${MESI[mese - 1]} ${anno} è finito: scegli il mese prossimo.`);
  const disponibili = giorni - inizio + 1;
  if (inizio <= giorni && conteggi.storie > disponibili) errori.push(`Al massimo una storia al giorno: in ${MESI[mese - 1]} restano ${disponibili} giorni.`);
  if (inizio <= giorni && conteggi.reel + conteggi.foto > disponibili) errori.push(`Troppi reel e foto per i ${disponibili} giorni che restano: al massimo uno al giorno.`);
  periodo = { anno, mese, nome_mese: MESI[mese - 1], giorni, giorno_inizio: inizio, primo_giorno: GIORNI[giornoSettimana(anno, mese, 1)] };
}

// Il cliente: si cerca per «cliente» o per «nome_locale», senza badare a maiuscole e spazi.
const chiave = testo(f.cliente).toLowerCase();
const riga = righe.find((r) => testo(r.cliente).toLowerCase() === chiave) || righe.find((r) => testo(r.nome_locale).toLowerCase() === chiave);
if (!chiave) errori.push('Manca il cliente.');
else if (!riga) errori.push(`Il cliente «${testo(f.cliente)}» non c'è nella scheda Clienti. Clienti presenti: ${righe.map((r) => testo(r.cliente)).join(', ') || 'nessuno'}.`);

return [{
  json: {
    ok: errori.length === 0,
    messaggio_errore: errori.join(' '),
    cliente: riga ? schedaCliente(riga) : null,
    periodo,
    conteggi,
    note_mese: testo(f.note),
  },
}];

