// Legge la risposta di Claude con il piano. Se qualcosa non torna, il piano non si scrive.
// ── Funzioni di servizio (le stesse in tutti i nodi Code dei workflow 03 e 04) ──
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const taglia = (v, n) => { const s = testo(v); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
// Telegram usa il "Markdown semplice": i caratteri _ * ` [ dei testi vanno neutralizzati,
// altrimenti Telegram rifiuta il messaggio. Dentro il *grassetto* non si mettono mai testi variabili.
const md = (v) => testo(v).replace(/\\/g, '/').replace(/([_*`[])/g, '\\$1');
const unisci = (righe) => righe.filter((r) => r !== null && r !== undefined && r !== false)
  .join('\n').replace(/\n{3,}/g, '\n\n').trim();
// «si/no» del foglio: accetta sì, si, yes, true, x… Se la cella è vuota vale «seVuoto».
const siNo = (v, seVuoto) => {
  const t = testo(v).toLowerCase();
  if (!t) return seVuoto;
  return ['si', 'sì', 'yes', 'true', 'vero', '1', 'x', 'ok'].includes(t);
};
const slug = (s) => testo(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '') || 'senza-nome';
const due = (n) => String(n).padStart(2, '0');
const GIORNI = ['domenica', 'lunedì', 'martedì', 'mercoledì', 'giovedì', 'venerdì', 'sabato'];
const GIORNI_BREVI = ['dom', 'lun', 'mar', 'mer', 'gio', 'ven', 'sab'];
const MESI = ['gennaio', 'febbraio', 'marzo', 'aprile', 'maggio', 'giugno', 'luglio', 'agosto', 'settembre', 'ottobre', 'novembre', 'dicembre'];
const giornoSettimana = (anno, mese, giorno) => new Date(Date.UTC(anno, mese - 1, giorno)).getUTCDay();
const giorniNelMese = (anno, mese) => new Date(Date.UTC(anno, mese, 0)).getUTCDate();
// Oggi a Roma: { anno, mese, giorno, ore, minuti }
const oggiRoma = () => {
  const p = {};
  for (const x of new Intl.DateTimeFormat('it-IT', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date())) p[x.type] = x.value;
  return { anno: Number(p.year), mese: Number(p.month), giorno: Number(p.day), ore: Number(p.hour), minuti: Number(p.minute) };
};
// data_ora del Calendario → { anno, mese, giorno, ore, minuti, chiave: 'AAAA-MM-GG HH:MM', leggibile: 'ven 5/12 ore 19:00' } o null.
// Accetta il testo scritto dai workflow (2026-12-05 19:30), le date all'italiana e il numero seriale di Google Sheets.
const leggiDataOra = (v) => {
  let a; let me; let g; let o; let mi;
  if (typeof v === 'number' && isFinite(v)) {
    const t = new Date(Date.UTC(1899, 11, 30) + Math.round(v * 86400000));
    [a, me, g, o, mi] = [t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate(), t.getUTCHours(), t.getUTCMinutes()];
  } else {
    const s = testo(v).replace(/\s+/g, ' ');
    let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2})[:.](\d{2})/);
    if (m) [a, me, g, o, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    else {
      m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4}),? (\d{1,2})[:.](\d{2})/);
      if (!m) return null;
      [g, me, a, o, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    }
  }
  if (!(me >= 1 && me <= 12 && g >= 1 && g <= giorniNelMese(a, me) && o >= 0 && o <= 23 && mi >= 0 && mi <= 59)) return null;
  return { anno: a, mese: me, giorno: g, ore: o, minuti: mi, chiave: `${a}-${due(me)}-${due(g)} ${due(o)}:${due(mi)}`,
    leggibile: `${GIORNI_BREVI[giornoSettimana(a, me, g)]} ${g}/${me} ore ${due(o)}:${due(mi)}` };
};
// La scheda del cliente dal foglio Clienti, con i campi nuovi già puliti.
const schedaCliente = (r) => ({
  cliente: testo(r.cliente),
  nome_locale: testo(r.nome_locale) || testo(r.cliente),
  attivo: siNo(r.attivo, false),
  tono_di_voce: testo(r.tono_di_voce),
  orari: testo(r.orari),
  link_prenotazione: testo(r.link_prenotazione),
  telefono: testo(r.telefono),
  indirizzo: testo(r.indirizzo),
  link_menu: testo(r.link_menu),
  regole: testo(r.regole_risposte),
  id_luogo: testo(r.id_luogo),
  account_da_taggare: testo(r.account_da_taggare),
  hashtag_fissi: testo(r.hashtag_fissi),
  note_piano: testo(r.note_piano),
  approvazione_testi: siNo(r.approvazione_testi, true), // vuoto = si: nel dubbio decide una persona
  esempi_didascalie: testo(r.esempi_didascalie),
  menu_testo: testo(r.menu_testo),
});
// Il testo che arriva dal foglio è un DATO: non deve poter aprire o chiudere i tag del prompt.
const datoPulito = (v) => testo(v).replace(/</g, '‹').replace(/>/g, '›');
// «esempi_didascalie»: da 3 a 5 didascalie separate da una riga con solo «---». Ne tengo al massimo 5.
const esempiDiStile = (v) => testo(v).split(/\r?\n\s*-{3,}\s*(?:\r?\n|$)/).map((x) => taglia(x, 1200)).filter(Boolean).slice(0, 5);
// Le righe della scheda Esempi di un cliente, le più recenti prima (per data, poi per posizione nel foglio).
const esempiDelCliente = (righe, cliente, fonti, quanti) => righe
  .filter((r) => r && testo(r.cliente).toLowerCase() === testo(cliente).toLowerCase() && fonti.includes(testo(r.fonte).toLowerCase()) && testo(r.testo))
  .map((r) => ({ data: leggiDataOra(r.data_ora), riga: Number(r.row_number) || 0, tipo: testo(r.tipo).toLowerCase(), fonte: testo(r.fonte).toLowerCase(),
    testo: taglia(r.testo, 800), metriche: taglia(r.metriche, 200) }))
  .sort((a, b) => ((b.data && b.data.chiave) || '').localeCompare((a.data && a.data.chiave) || '') || b.riga - a.riga)
  .slice(0, quanti)
  .map(({ data, riga, ...x }) => ({ ...x, data_ora: data ? data.chiave : '' }));
// ── fine funzioni di servizio ──
const { prompt_sistema, messaggio_utente, ...d } = $('Prepara la domanda per il piano').first().json;
const r = $input.first().json || {};
const TIPI = ['post', 'carosello', 'reel', 'storia'];

let piano = null;
let errore = '';
if (typeof r.statusCode !== 'number') errore = 'Claude non raggiungibile';
else if (r.statusCode !== 200) errore = 'Claude ha risposto con un errore (HTTP ' + r.statusCode + (r.body && r.body.error && r.body.error.message ? ': ' + r.body.error.message : '') + ')';
else if (r.body && r.body.stop_reason === 'refusal') errore = 'Claude non ha voluto preparare questo piano';
else if (r.body && r.body.stop_reason === 'max_tokens') errore = 'la risposta di Claude è stata troncata (troppo lunga)';
else {
  // Prima possono esserci blocchi di "ragionamento" (thinking): si prende il primo blocco di testo.
  const blocco = ((r.body && r.body.content) || []).find((x) => x && x.type === 'text');
  if (!blocco) errore = 'risposta di Claude senza testo';
  else { try { piano = JSON.parse(blocco.text); } catch (e) { errore = 'risposta di Claude non leggibile'; } }
}
if (piano && !(piano && Array.isArray(piano.contenuti) && piano.contenuti.every((x) => x && TIPI.includes(x.tipo)
  && Number.isInteger(x.giorno) && typeof x.ora === 'string' && typeof x.idea === 'string' && typeof x.da_riprendere === 'string'
  && typeof x.zona === 'string' && typeof x.dal_vivo === 'boolean'))) {
  piano = null;
  errore = 'piano di Claude incompleto';
}
const uso = (r.body && r.body.usage) || {};
return [{
  json: {
    ...d,
    ai_ok: !!piano,
    ai_errore: errore,
    contenuti_ai: piano ? piano.contenuti : [],
    note_ai: piano ? testo(piano.note_per_il_team) : '',
    token_ingresso: Number(uso.input_tokens) || 0,
    token_uscita: Number(uso.output_tokens) || 0,
  },
}];

// Controlla il piano di Claude: date dentro il mese, orari validi, numeri giusti, id unici.
// Prepara le righe per il Calendario, i messaggi per Telegram e la risposta del modulo.
// ── Funzioni di servizio (le stesse in tutti i nodi Code dei workflow 03 e 04) ──
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const taglia = (v, n) => { const s = testo(v); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
// Telegram usa il "Markdown semplice": i caratteri _ * ` [ dei testi vanno neutralizzati,
// altrimenti Telegram rifiuta il messaggio. Dentro il *grassetto* non si mettono mai testi variabili.
const md = (v) => testo(v).replace(/\\/g, '/').replace(/([_*`[])/g, '\\$1');
const unisci = (righe) => righe.filter((r) => r !== null && r !== undefined && r !== false)
  .join('\n').replace(/\n{3,}/g, '\n\n').trim();
// «si/no» del foglio: accetta sì, si, yes, true, x… Se la cella è vuota vale «seVuoto».
const siNo = (v, seVuoto) => {
  const t = testo(v).toLowerCase();
  if (!t) return seVuoto;
  return ['si', 'sì', 'yes', 'true', 'vero', '1', 'x', 'ok'].includes(t);
};
const slug = (s) => testo(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '') || 'senza-nome';
const due = (n) => String(n).padStart(2, '0');
const GIORNI = ['domenica', 'lunedì', 'martedì', 'mercoledì', 'giovedì', 'venerdì', 'sabato'];
const GIORNI_BREVI = ['dom', 'lun', 'mar', 'mer', 'gio', 'ven', 'sab'];
const MESI = ['gennaio', 'febbraio', 'marzo', 'aprile', 'maggio', 'giugno', 'luglio', 'agosto', 'settembre', 'ottobre', 'novembre', 'dicembre'];
const giornoSettimana = (anno, mese, giorno) => new Date(Date.UTC(anno, mese - 1, giorno)).getUTCDay();
const giorniNelMese = (anno, mese) => new Date(Date.UTC(anno, mese, 0)).getUTCDate();
// Oggi a Roma: { anno, mese, giorno, ore, minuti }
const oggiRoma = () => {
  const p = {};
  for (const x of new Intl.DateTimeFormat('it-IT', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date())) p[x.type] = x.value;
  return { anno: Number(p.year), mese: Number(p.month), giorno: Number(p.day), ore: Number(p.hour), minuti: Number(p.minute) };
};
// data_ora del Calendario → { anno, mese, giorno, ore, minuti, chiave: 'AAAA-MM-GG HH:MM', leggibile: 'ven 5/12 ore 19:00' } o null.
// Accetta il testo scritto dai workflow (2026-12-05 19:30), le date all'italiana e il numero seriale di Google Sheets.
const leggiDataOra = (v) => {
  let a; let me; let g; let o; let mi;
  if (typeof v === 'number' && isFinite(v)) {
    const t = new Date(Date.UTC(1899, 11, 30) + Math.round(v * 86400000));
    [a, me, g, o, mi] = [t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate(), t.getUTCHours(), t.getUTCMinutes()];
  } else {
    const s = testo(v).replace(/\s+/g, ' ');
    let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2})[:.](\d{2})/);
    if (m) [a, me, g, o, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    else {
      m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4}),? (\d{1,2})[:.](\d{2})/);
      if (!m) return null;
      [g, me, a, o, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    }
  }
  if (!(me >= 1 && me <= 12 && g >= 1 && g <= giorniNelMese(a, me) && o >= 0 && o <= 23 && mi >= 0 && mi <= 59)) return null;
  return { anno: a, mese: me, giorno: g, ore: o, minuti: mi, chiave: `${a}-${due(me)}-${due(g)} ${due(o)}:${due(mi)}`,
    leggibile: `${GIORNI_BREVI[giornoSettimana(a, me, g)]} ${g}/${me} ore ${due(o)}:${due(mi)}` };
};
// La scheda del cliente dal foglio Clienti, con i campi nuovi già puliti.
const schedaCliente = (r) => ({
  cliente: testo(r.cliente),
  nome_locale: testo(r.nome_locale) || testo(r.cliente),
  attivo: siNo(r.attivo, false),
  tono_di_voce: testo(r.tono_di_voce),
  orari: testo(r.orari),
  link_prenotazione: testo(r.link_prenotazione),
  telefono: testo(r.telefono),
  indirizzo: testo(r.indirizzo),
  link_menu: testo(r.link_menu),
  regole: testo(r.regole_risposte),
  id_luogo: testo(r.id_luogo),
  account_da_taggare: testo(r.account_da_taggare),
  hashtag_fissi: testo(r.hashtag_fissi),
  note_piano: testo(r.note_piano),
  approvazione_testi: siNo(r.approvazione_testi, true), // vuoto = si: nel dubbio decide una persona
  esempi_didascalie: testo(r.esempi_didascalie),
  menu_testo: testo(r.menu_testo),
});
// Il testo che arriva dal foglio è un DATO: non deve poter aprire o chiudere i tag del prompt.
const datoPulito = (v) => testo(v).replace(/</g, '‹').replace(/>/g, '›');
// «esempi_didascalie»: da 3 a 5 didascalie separate da una riga con solo «---». Ne tengo al massimo 5.
const esempiDiStile = (v) => testo(v).split(/\r?\n\s*-{3,}\s*(?:\r?\n|$)/).map((x) => taglia(x, 1200)).filter(Boolean).slice(0, 5);
// Le righe della scheda Esempi di un cliente, le più recenti prima (per data, poi per posizione nel foglio).
const esempiDelCliente = (righe, cliente, fonti, quanti) => righe
  .filter((r) => r && testo(r.cliente).toLowerCase() === testo(cliente).toLowerCase() && fonti.includes(testo(r.fonte).toLowerCase()) && testo(r.testo))
  .map((r) => ({ data: leggiDataOra(r.data_ora), riga: Number(r.row_number) || 0, tipo: testo(r.tipo).toLowerCase(), fonte: testo(r.fonte).toLowerCase(),
    testo: taglia(r.testo, 800), metriche: taglia(r.metriche, 200) }))
  .sort((a, b) => ((b.data && b.data.chiave) || '').localeCompare((a.data && a.data.chiave) || '') || b.riga - a.riga)
  .slice(0, quanti)
  .map(({ data, riga, ...x }) => ({ ...x, data_ora: data ? data.chiave : '' }));
// ── fine funzioni di servizio ──
const d = $input.first().json;
const c = d.cliente;
const p = d.periodo;
const k = d.conteggi;
const avvisi = [];

if (!d.ai_ok) {
  return [{ json: { ok: false, righe: [], messaggi: [
    unisci([`⚠️ *Piano non creato* · ${md(c.nome_locale)} · ${md(p.nome_mese)} ${p.anno}`, `Motivo: ${md(d.ai_errore)}.`,
      'Nel Calendario non è stato scritto niente: rimandate il modulo tra qualche minuto.']),
  ], messaggio_modulo: `Non sono riuscito a creare il piano: ${d.ai_errore}. Nel Calendario non è stato scritto niente: riprova tra qualche minuto.` } }];
}

const ZONE = ['piatti e drink', 'bancone', 'cucina', 'sala', 'esterno', 'staff', 'altro'];
const ORA_DI_RISERVA = { post: '12:30', carosello: '12:30', reel: '19:00', storia: '11:00' };
const GRUPPO = { reel: 'reel', post: 'foto', carosello: 'foto', storia: 'storie' };

// 1) Ogni contenuto: giorno dentro il mese, ora valida e ragionevole (06:00-23:30), idea presente.
const validi = [];
let fuoriMese = 0;
let orariCorretti = 0;
for (const x of d.contenuti_ai) {
  if (!(x.giorno >= p.giorno_inizio && x.giorno <= p.giorni)) { fuoriMese++; continue; }
  if (!testo(x.idea)) continue;
  let ora = testo(x.ora);
  const m = ora.match(/^(\d{1,2})[:.](\d{2})$/);
  const minuti = m ? Number(m[1]) * 60 + Number(m[2]) : -1;
  if (!m || Number(m[1]) > 23 || Number(m[2]) > 59 || minuti < 6 * 60 || minuti > 23 * 60 + 30) { ora = ORA_DI_RISERVA[x.tipo]; orariCorretti++; }
  else ora = `${due(Number(m[1]))}:${m[2]}`;
  const zona = ZONE.includes(testo(x.zona).toLowerCase()) ? testo(x.zona).toLowerCase() : 'altro';
  validi.push({ tipo: x.tipo, giorno: x.giorno, ora, idea: testo(x.idea), da_riprendere: testo(x.da_riprendere), zona,
    dal_vivo: x.tipo === 'storia' && x.dal_vivo === true });
}
if (fuoriMese) avvisi.push(`${fuoriMese} contenuti erano fuori dai giorni del mese: scartati`);
if (orariCorretti) avvisi.push(`${orariCorretti} orari non validi sostituiti con un orario standard`);

// 2) I numeri: se Claude ne propone di più tengo i primi in ordine di data, se ne propone meno lo segnalo.
validi.sort((a, b) => a.giorno - b.giorno || a.ora.localeCompare(b.ora));
const richiesti = { reel: k.reel, foto: k.foto, storie: k.storie };
const nomi = { reel: 'reel', foto: 'foto o caroselli', storie: 'storie' };
const tenuti = [];
for (const gruppo of ['reel', 'foto', 'storie']) {
  const delGruppo = validi.filter((x) => GRUPPO[x.tipo] === gruppo);
  if (delGruppo.length > richiesti[gruppo]) avvisi.push(`Claude ha proposto ${delGruppo.length} ${nomi[gruppo]} invece di ${richiesti[gruppo]}: tenuti i primi ${richiesti[gruppo]}`);
  if (delGruppo.length < richiesti[gruppo]) avvisi.push(`mancano ${richiesti[gruppo] - delGruppo.length} ${nomi[gruppo]} (aggiungeteli a mano)`);
  tenuti.push(...delGruppo.slice(0, richiesti[gruppo]));
}
tenuti.sort((a, b) => a.giorno - b.giorno || a.ora.localeCompare(b.ora));

// 3) Le regole del piano (si segnalano, non si correggono: il piano resta in «idea» e lo rivede il team).
const conta = (filtro) => { const n = {}; for (const x of tenuti.filter(filtro)) n[x.giorno] = (n[x.giorno] || 0) + 1; return n; };
const feedPerGiorno = conta((x) => x.tipo !== 'storia');
const storiePerGiorno = conta((x) => x.tipo === 'storia');
const doppiFeed = Object.keys(feedPerGiorno).filter((g) => feedPerGiorno[g] > 1);
const doppieStorie = Object.keys(storiePerGiorno).filter((g) => storiePerGiorno[g] > 1);
if (doppiFeed.length) avvisi.push(`più di un reel/post nello stesso giorno: ${doppiFeed.join(', ')} ${p.nome_mese}`);
if (doppieStorie.length) avvisi.push(`più di una storia nello stesso giorno: ${doppieStorie.join(', ')} ${p.nome_mese}`);
const nelleChiusure = tenuti.filter((x) => d.giorni_chiusura.includes(giornoSettimana(p.anno, p.mese, x.giorno)));
if (nelleChiusure.length) avvisi.push(`${nelleChiusure.length} contenuti cadono in un giorno di chiusura (${[...new Set(nelleChiusure.map((x) => x.giorno))].join(', ')} ${p.nome_mese}): spostateli`);
const giorniGiaUsati = new Set(d.gia_presenti.filter((x) => x.tipo !== 'storia').map((x) => x.giorno));
const sovrapposti = tenuti.filter((x) => x.tipo !== 'storia' && giorniGiaUsati.has(x.giorno));
if (sovrapposti.length) avvisi.push(`${sovrapposti.length} contenuti cadono in giorni che avevano già un post: ${[...new Set(sovrapposti.map((x) => x.giorno))].join(', ')}`);

// 4) Id unici, anche rispetto a quelli già nel Calendario: cliente-AAAAMMGG-hhmm (con -2, -3… se serve).
const usati = new Set(d.ids_esistenti.map((x) => x.toLowerCase()));
const righe = tenuti.map((x) => {
  const base = `${slug(c.cliente)}-${p.anno}${due(p.mese)}${due(x.giorno)}-${x.ora.replace(':', '')}`;
  let id = base;
  for (let n = 2; usati.has(id.toLowerCase()); n++) id = `${base}-${n}`;
  usati.add(id.toLowerCase());
  const riprese = x.dal_vivo ? `dal vivo, il giorno stesso al locale (${x.zona}): ${x.da_riprendere}` : `(${x.zona}) ${x.da_riprendere}`;
  return { id, cliente: c.cliente, tipo: x.tipo, piattaforme: 'ig+fb', data_ora: `${p.anno}-${due(p.mese)}-${due(x.giorno)} ${x.ora}`,
    brief: `Idea: ${x.idea}\nDa riprendere ${riprese}`, stato: 'idea', note: 'piano AI', _zona: x.zona, _dal_vivo: x.dal_vivo,
    _da_riprendere: x.da_riprendere };
});

if (!righe.length) {
  return [{ json: { ok: false, righe: [], messaggi: [
    unisci([`⚠️ *Piano non creato* · ${md(c.nome_locale)} · ${md(p.nome_mese)} ${p.anno}`, 'Il piano di Claude non conteneva contenuti validi per questo mese.']),
  ], messaggio_modulo: 'Non sono riuscito a creare il piano: nessun contenuto valido. Riprova tra qualche minuto.' } }];
}

// 5) I messaggi per Telegram (spezzati sotto i 3.500 caratteri) e la risposta del modulo.
const quanti = (t) => righe.filter((x) => x.tipo === t).length;
const dalVivo = righe.filter((x) => x._dal_vivo).length;
const quando = (x) => { const g = Number(x.data_ora.slice(8, 10)); return `${GIORNI_BREVI[giornoSettimana(p.anno, p.mese, g)]} ${g}/${p.mese} ${x.data_ora.slice(11)}`; };
const riepilogo = unisci([
  `🗓️ *Piano del mese pronto* · ${md(c.nome_locale)} · ${md(p.nome_mese)} ${p.anno}`,
  `Nel Calendario ci sono ${righe.length} righe nuove in stato «idea»: ${quanti('reel')} reel, ${quanti('post')} post, ${quanti('carosello')} caroselli, ${quanti('storia')} storie (${dalVivo} dal vivo).`,
  d.note_ai ? `*Logica:* ${md(d.note_ai)}` : null,
  d.festivita.length ? `*Festività:* ${md(d.festivita.join('; '))}` : null,
  avvisi.length ? `⚠️ *Da controllare:*\n${avvisi.map((a) => '• ' + md(a)).join('\n')}` : null,
  `*Prossimo passo:* dopo le riprese mettete i file nella colonna «media» e lo stato «${md('da_scrivere')}»: i testi li scrive il workflow 04.`,
]);
// La lista delle riprese, divisa per zona del locale. Si spezza riga per riga: nessun messaggio supera 3.500 caratteri.
const titoloLista = `🎬 *Lista delle riprese* · ${md(c.nome_locale)} · ${md(p.nome_mese)} ${p.anno}`;
const righeLista = [];
for (const zona of ZONE) {
  const daGirare = righe.filter((x) => !x._dal_vivo && x._zona === zona);
  if (!daGirare.length) continue;
  righeLista.push('', `*${zona.charAt(0).toUpperCase() + zona.slice(1)}* (${daGirare.length})`);
  for (const x of daGirare) righeLista.push(`• ${x.tipo} · ${quando(x)} · ${md(taglia(x._da_riprendere, 300))}`);
}
const messaggi = [riepilogo];
if (righeLista.length) {
  let corrente = unisci([titoloLista, dalVivo ? `Le ${dalVivo} storie dal vivo si girano il giorno stesso: qui non ci sono.` : null]);
  for (const r of righeLista) {
    if ((corrente + '\n' + r).length > 3500) { messaggi.push(corrente.trim()); corrente = `${titoloLista} (continua)`; }
    corrente += '\n' + r;
  }
  messaggi.push(corrente.trim());
}

return [{
  json: {
    ok: true,
    righe: righe.map(({ _zona, _dal_vivo, _da_riprendere, ...r }) => r),
    messaggi,
    avvisi,
    messaggio_modulo: `Piano creato: ${righe.length} righe nel Calendario per ${c.nome_locale} (${p.nome_mese} ${p.anno}). `
      + 'Il riepilogo e la lista delle riprese sono su Telegram.' + (avvisi.length ? ` Da controllare: ${avvisi.length} cose, scritte su Telegram.` : ''),
  },
}];
